package com.brainserve.onboarding.forms.infrastructure.persistence;
import com.brainserve.onboarding.forms.domain.model.*; import jakarta.persistence.LockModeType; import java.util.*; import org.springframework.data.domain.*; import org.springframework.data.jpa.repository.*; import org.springframework.data.repository.query.Param;
public interface FormTemplateRepository extends JpaRepository<FormTemplate,UUID>{ Optional<FormTemplate> findByOrganizationIdAndId(UUID organizationId,UUID id); Page<FormTemplate> findAllByOrganizationIdAndStatus(UUID organizationId,FormStatus status,Pageable pageable); Page<FormTemplate> findAllByOrganizationId(UUID organizationId,Pageable pageable); boolean existsByOrganizationIdAndNameIgnoreCaseAndStatus(UUID organizationId,String name,FormStatus status); boolean existsByOrganizationIdAndNameIgnoreCaseAndStatusAndIdNot(UUID organizationId,String name,FormStatus status,UUID id); @Lock(LockModeType.PESSIMISTIC_WRITE) @Query("select f from FormTemplate f where f.organizationId=:org and f.id=:id") Optional<FormTemplate> findForUpdate(@Param("org")UUID org,@Param("id")UUID id); }
